 if(!ids.length&&!pids.length)return{status:'info',items:[{level:'info',title:'Add animals or plants',text:'Use the Livestock and Plants steps to fill your tank.',ic:'plus'}],pct:0,pctA:0,v,ids,sp,pl,temp:null,ph:null,lv:{t:0,m:0,b:0}};
 if(eq.filter==='none'&&ids.length&&!sp.every(s=>s.body==='snail'))add('bad','No filter','Waste turns into toxic ammonia within days. Add a filter rated for at least '+recFlow(v)+' L/h.',null,'filter');
