 sp.forEach(s=>{const G=fishGroups(p,s.id);if(G.length<2||!s.prey)return;const cms=G.map(g=>effCm(s,g.size));const big=Math.max(...cms),small=Math.min(...cms);if(small<=s.prey*Math.min(1,big/s.cm))add('warn',`Big ${s.n}s may eat the small ones`,`Your largest ${plw(s.n.toLowerCase())} (~${r1(big)} cm) can swallow tankmates up to ~${r1(s.prey*Math.min(1,big/s.cm))} cm. Grow the small ones out separately.`,null,'growth');else if(big>small*2.5)add('info',`Mixed ${s.n} sizes`,'Large size differences can lead to bullying at feeding time. Feed in two spots.',null,'users')});
 const SI=subInfo(eq);
