 if(eq.flow>v.net*10&&sp.some(s=>s.lf||s.cat==='Gouramis & Bettas'||s.body==='shrimp'||s.id==='peapuffer'))add('warn','Very strong current',`${Math.round(eq.flow)} L/h is over 10× the volume. Long-finned fish, bettas and shrimp prefer calm water: baffle the outflow or use a spray bar.`,null,'wave');
