function go(v,extra){if(v==='community'&&!(extra&&extra.keepcm)&&S.cm){S.cm.post=null;S.cm.user=null}Object.assign(S,{view:v},extra||{});delete S.keepcm;S.modal=[];closeSheet(true);render();window.scrollTo({top:0});try{history.replaceState(null,'','#'+v)}catch(e){}}

