const themeNow=()=>document.documentElement.dataset.theme||(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark');
const st=store.get('tm3-theme');if(st)document.documentElement.dataset.theme=st;
function paintHeader(){const L=lvlOf(game.xp),act=S.tanks.length;
 $('#logo').innerHTML=D.logo(36)+D.wordmark();
 $('#hdrR').innerHTML=`<button class="lvl${USER&&USER.joined?'':' guest'}" data-sheet="trophy" aria-label="Level and badges"><i>${L+1}</i><span>${game.xp} XP</span>${(game.streak&&game.streak.n>1)?`<em class="stk">${I('flame',13)}${game.streak.n}</em>`:''}</button>
 <button class="hbtn attn${game.st.scans?'':' strong'}" data-scan aria-label="Scan a fish with the camera (AI)" title="AI fish scanner">${I('scan',20)}<span class="aidot">AI</span></button>
 <button class="hbtn" data-sheet="mytanks" aria-label="My tanks: ${act}" title="My tanks">${I('tank',20)}${act?`<span class="dot">${act}</span>`:''}</button>
 <button class="hbtn" data-sound aria-pressed="${!!prefs.sound}" aria-label="Sound effects ${prefs.sound?'on':'off'}" title="Sound ${prefs.sound?'on':'off'}">${I(prefs.sound?'vol':'mute',20)}</button>
 <button class="hbtn hide-s" id="themeBtn" aria-label="Switch light or dark mode" title="${themeNow()==='dark'?'Light mode':'Dark mode'}">${I(themeNow()==='dark'?'sun':'moon',20)}</button>
 ${window.__cmReady?`<button class="hbtn" data-sheet="c:notif" aria-label="Notifications" title="Notifications">${I('bell',20)}${unread()?`<span class="dot">${unread()}</span>`:''}</button>`:''}${!(USER&&USER.joined)?`<button class="loginbtn" data-login aria-label="Log in or sign up">${I('user',17)}<span>Log in</span></button>`:''}${!(USER&&USER.joined)?'':(()=>{const pu=window.__cmReady?me():null,nm=(pu&&pu.name&&pu.name!=='Aquarist'?pu.name:(USER&&USER.name))||'';return `<button class="hbtn avatar${pu&&pu.photo?' hasph':''}" data-sheet="profile" aria-label="My profile${nm?': '+esc(nm):''}${needVerify()?' (email not confirmed)':''}" title="${nm?esc(nm):'My profile'}" ${pu&&!pu.photo?`style="background:linear-gradient(135deg,${pu.color},color-mix(in srgb,${pu.color} 45%,#0B1B22))"`:''}>${pu&&pu.photo?`<img src="${pu.photo}" alt="">`:nm?esc(nm.trim()[0].toUpperCase()):I('user',20)}`})()}${USER&&USER.joined?(needVerify()?'<span class="dot" style="background:var(--warn)">!</span>':'')+'</button>':''}`}
document.addEventListener('click',e=>{if(e.target.closest('#themeBtn')){const t=themeNow()==='dark'?'light':'dark';document.documentElement.dataset.theme=t;store.set('tm3-theme',t);paintHeader();if(S.sheet==='profile')renderSheet()}});

