const diffBadge=c=>`<span class="diff d${c}" title="Difficulty: ${CARE[c]}"><span class="bars">${[1,2,3].map(i=>`<i class="${i<=c?'f':''}" style="height:${4+i*3}px"></i>`).join('')}</span>${CARE[c]}</span>`;
const pill=(st,t)=>`<span class="pill ${st}">${esc(t||{good:'Compatible',warn:'Needs care',bad:'Problems found',info:'Not checked'}[st])}</span>`;
function media(x,o={}){if(x.kind==='sp'||x.kind==='pl'||D.hasIll(x.id))return `<img class="ill${D.hasIll(x.id)?'':' ghost'}" src="${D.src(x.id)}" alt="${esc(x.n)}" loading="lazy">${D.hasIll(x.id)?'':`<span class="soonpic">${I('camera',12)}Illustration coming soon</span>`}`;
 if(x.kind==='dz')return D.diseaseDiagram(x,true);return D.ill(x.ill,x.col)}
const thumb=x=>`<span class="th">${x.kind==='sp'||x.kind==='pl'||D.hasIll(x.id)?`<img src="${D.src(x.id)}" alt="" loading="lazy">`:x.kind==='dz'?I('virus'):D.ill(x.ill,x.col)}</span>`;
function spIcons(s,short){return `<span class="ic ${s.tm}" title="${TM[s.tm]}">${I(TMI[s.tm])}${short?'':TM[s.tm]}</span><span class="ic" title="Swims: ${LVL[s.lvl]}">${I(LVI[s.lvl])}${LVL[s.lvl]}</span><span class="ic" title="Adult size">${I('ruler')}${s.cm} cm</span>${short?'':`<span class="ic" title="Temperature">${I('thermo')}${s.t[0]}–${s.t[1]}°</span>`}`}
function plIcons(x){return `<span class="ic" title="Light">${I('bulb')}${LIGHT[x.light]}</span><span class="ic" title="CO2">${I('co2')}CO₂ ${['no','opt.','yes'][x.co2]}</span><span class="ic" title="Position">${I('layers')}${POS[x.pos]}</span>`}
function card(x){const sub=x.kind==='sp'||x.kind==='pl'?`<div class="sci">${esc(x.sci)}</div>`:x.kind==='dz'?`<div class="sci" style="font-style:normal">${esc(x.signs[0])}</div>`:`<div class="sci" style="font-style:normal">${esc((x.ex||[]).slice(0,2).join(' · '))}</div>`;
 const icons=x.kind==='sp'?spIcons(x):x.kind==='pl'?plIcons(x):x.kind==='dz'?`<span class="ic ${['','p','s','a'][x.sev]}">${I('alert')}${['','Mild','Serious','Urgent'][x.sev]}</span>`:x.kind==='med'?`<span class="ic">${I('virus')}${x.dz.length} condition${x.dz.length===1?'':'s'}</span>`:`<span class="ic">${I('users')}${esc((x.for||'').split(',')[0])}</span>`;
 const price=x.usd?`<span class="ic price">${I('coins')}${prs(x.usd,1,x.kind==='sp')}</span>`:'';
 const acts=x.kind==='sp'?`<div class="cardacts"><button class="btn sm" data-addplan="${x.id}">${I('plus',15)}Add to tank</button><button class="btn sm ghost" data-cmp="${x.id}">${I('vs',15)}Compare</button></div>`:x.kind==='pl'?`<div class="cardacts"><button class="btn sm" data-addplan="${x.id}">${I('plus',15)}Add to tank</button></div>`:'';
 return `<article class="card"><button class="ph" data-open="${x.id}" aria-label="Open ${esc(x.n)}">${media(x)}<span class="ovl">${x.care?diffBadge(x.care):''}</span>${window.__ecoReady&&CMD.irate[x.id]&&CMD.irate[x.id].o?`<span class="irb">★ ${CMD.irate[x.id].o}</span>`:''}</button><div class="body"><span class="ccat">${esc(x.cat)}</span><button class="nm" data-open="${x.id}">${esc(x.n)}</button>${sub}<div class="icons">${icons}${price}</div>${acts}</div></article>`}
const flagOf=cc=>cc&&cc.length===2?String.fromCodePoint(...[...cc.toUpperCase()].map(c=>127397+c.charCodeAt(0))):'';
const NSYM={USD:'$',EUR:'€',GBP:'£',AED:'د.إ',SAR:'ر.س',QAR:'ر.ق',KWD:'د.ك',BHD:'د.ب',OMR:'ر.ع.',IRR:'﷼',IQD:'ع.د',JOD:'د.ا',EGP:'E£',INR:'₹',CNY:'¥',JPY:'¥',KRW:'₩',RUB:'₽',TRY:'₺',AUD:'A$',CAD:'C$',BRL:'R$',SGD:'S$',THB:'฿',CHF:'Fr',SEK:'kr',NOK:'kr',DKK:'kr',PLN:'zł',CZK:'Kč',HUF:'Ft',PKR:'₨',HKD:'HK$',TWD:'NT$',IDR:'Rp',MYR:'RM',PHP:'₱',VND:'₫',ZAR:'R',NGN:'₦',MXN:'$',NZD:'NZ$',ILS:'₪',LBP:'ل.ل'};
