function dScale(t,dir){const k=S.dSel;if(!k)return;const svg=$('#dstage svg');const g=svg&&svg.querySelector(`[data-k="${CSS.escape(k)}"]`);let cur=t.layout[k];if(!cur&&g&&svg){const [fx,fw,tf,tb,dxd,dyd]=svg.dataset.geo.split(',').map(Number);const bb=g.getBBox();const z=clamp((bb.y+bb.height-tf)/((tb-tf)+dyd),0,1);cur={x:(bb.x+bb.width/2-fx-dxd*z)/fw,z,s:1}}if(!cur)return;cur.s=clamp((cur.s||1)*(dir>0?1.15:1/1.15),.4,2.5);t.layout[k]=cur;SFX('click');dSave(t);renderDesigner($('#modal'))}
