const tplVol=t=>Math.round((t.shape==='cube'?t.dims[0]**3:t.dims[0]*t.dims[1]*t.dims[2])/1000*.85);
function eqFromTpl(te){const e=defEq();if(!te)return e;const{substrate,filters,...rest}=te;Object.assign(e,rest);e.subs=Array.isArray(substrate)?substrate.map(l=>({id:l.id,cm:l.cm||3})):[{id:substrate||'sand_fine',cm:6}];e.filters=Array.isArray(filters)?filters.map(f=>({id:f.id,flow:f.flow||0})):(te.filter?[{id:te.filter,flow:0}]:[{id:'hob',flow:0}]);if(e.light==null)e.light='medium';return e}
function tplTank(t,type='future'){const p=newTank(type);p.name=t.n;p.shape=t.shape||'rect';[p.L,p.W,p.H]=t.dims;if(p.shape==='cube')p.S=t.dims[0];Object.entries(t.fish).forEach(([k,n])=>p.fish[k]={n,groups:[{n,size:BY[k]?.sized?1:undefined}]});p.plants={...t.plants};p.eq=eqFromTpl(t.eq);p.tpl=t.id;return prep(p)}
/* smart suggestions: scale proven templates to the user's tank, keep only ones that pass the check */
function suggestFor(p){prep(p);const v=vol(p);if(!(v.net>4))return[];const k=p.unit==='in'?2.54:1;const len=p.shape==='custom'?v.len:(p.shape==='cube'?+p.S:p.shape==='cyl'||p.shape==='bowl'?+p.D:+p.L)*k,dep=p.shape==='custom'?v.dep:(p.shape==='cube'?+p.S:p.shape==='cyl'||p.shape==='bowl'?+p.D:+p.W)*k;
 const out=[];TEMPLATES.forEach(t=>{const tv=tplVol(t),sc=v.net/tv;if(sc<.45||sc>3.2)return;const fish={};let okGeo=true;
  Object.entries(t.fish).forEach(([id,n])=>{const s=BY[id];if(s.minL>v.net*1.02||s.cm*3.2>len||(s.cm>=12&&s.cm*1.1>dep))okGeo=false;let m=n<=1||s.max1?n:Math.round(n*Math.min(sc,2.2));if(s.grp>1)m=Math.max(s.grp,m);if(m>0)fish[id]=m});
  if(!okGeo||!Object.keys(fish).length)return;
  const q=newTank(p.type);Object.assign(q,{shape:p.shape,unit:p.unit,L:p.L,W:p.W,H:p.H,D:p.D,S:p.S,custom:p.custom,name:t.n});
  Object.entries(fish).forEach(([id,n])=>q.fish[id]={n,groups:[{n,size:BY[id].sized?1:undefined}]});
  const ps=Math.sqrt(sc);Object.entries(t.plants||{}).forEach(([id,n])=>q.plants[id]=Math.max(1,Math.round(n*ps)));q.eq=eqFromTpl(t.eq);
  q.eq.filters=q.eq.filters.map(f=>({...f,flow:Math.round(Math.max(f.flow||0,v.net*5)/10)*10}));q.eq.heaterW=q.eq.heater?recHeat(v):0;q.tpl=t.id;q.tplGroup=t.group;
  const c=check(q);if(c.status==='bad'||c.pct<15||c.pct>92)return;
  out.push({p:q,t,c,score:-Math.abs(Math.log(sc))+(c.status==='good'?.6:0)+(c.pct>40&&c.pct<80?.3:0)})});
 out.sort((a,b)=>b.score-a.score);const pick=[],seen=new Set();out.forEach(o=>{if(pick.length<5&&!seen.has(o.t.group)){pick.push(o);seen.add(o.t.group)}});out.forEach(o=>{if(pick.length<5&&!pick.includes(o))pick.push(o)});return pick}
