 <div style="display:grid;gap:8px;margin-top:12px">${c.items.map((it,i)=>`<div class="issue ${it.level}">${CI(it.ic||'info',{good:'#45D483',warn:'#F6B740',bad:'#FF6A57',info:'#3AA8FF'}[it.level],34)}<div style="min-width:0"><b>${esc(it.title)}</b><span class="muted">${esc(it.text)}</span>${it.fix?`<div style="margin-top:6px"><button class="btn sm ghost" data-fix="${i}">${it.fix.remove?'Remove '+esc(BY[it.fix.remove].n):'Set to '+it.fix.set[1]}</button></div>`:''}</div></div>`).join('')}</div>
