function intank(isP){const p=S.plan;const ids=isP?Object.keys(p.plants).filter(k=>p.plants[k]>0):Object.keys(p.fish).filter(k=>p.fish[k].n>0);if(!ids.length)return '';return `<div class="intank">${ids.map(i=>`<span><img src="${D.src(i)}" alt="">${esc(BY[i].n)} ×${isP?p.plants[i]:p.fish[i].n}</span>`).join('')}</div>`}
function suggHtml(p){const L=suggestFor(p);const v=vol(p);if(!L.length)return `<div class="sugg0"><span class="eyebrow">${I('sparkle',15)} Smart suggestions</span><p class="sm muted" style="margin-top:6px">Enter a size above to see setups that fit ${Math.round(v.net)} L.</p></div>`;S.suggs=L;
 return `<div class="suggs"><div class="sechead" style="margin:18px 0 10px"><div><span class="eyebrow">${I('sparkle',15)} Smart suggestions</span><h3 style="margin-top:4px">Best setups for your ${Math.round(v.net)} L tank</h3></div></div><div class="sgrid">${L.map((o,i)=>{const q=o.p,ids=Object.keys(q.fish),cost=costOf(q);return `<div class="sgc"><div class="sgt">${tankSvg(q,{anim:false,h:200})}</div><div class="sgb"><div style="display:flex;justify-content:space-between;gap:6px;align-items:start"><b>${esc(o.t.n)}</b>${pill(o.c.status,o.c.status==='good'?'Compatible':'Check notes')}</div><span class="xs muted">${esc(o.t.group)} · ${esc(o.t.d)}</span>
  <div class="sgf">${ids.slice(0,5).map(id=>`<span title="${esc(BY[id].n)}"><img src="${D.src(id)}" alt="">${q.fish[id].n}</span>`).join('')}</div>
  <div class="xs muted">${ids.map(id=>q.fish[id].n+' '+esc(BY[id].n)).join(', ')} · ${Object.keys(q.plants).length} plant${(Object.keys(q.plants).length)===1?'':'s'} · ${mrange(cost.setup)}</div>
  <div style="display:flex;gap:6px;margin-top:8px"><button class="btn sm ghost" data-sgview="${i}">${I('eye',15)}Review</button><button class="btn sm grad" data-sguse="${i}">${I('check',15,3)}Use this</button></div></div></div>`}).join('')}</div></div>`}
function vTankDetail(t){const c=check(t),last=t.tests[t.tests.length-1],cost=costOf(t);
 const rows=c.ids.map(id=>{const s=BY[id];return `<div class="prow">${thumb(s)}<div><b>${esc(s.n)} × ${t.fish[id].n}</b><div class="xs muted">${esc(s.cat)}${t.fish[id].groups&&(s.var||s.sized)?' · '+grpSummary(s,t.fish[id]):''}</div></div><button class="btn sm ghost" data-rm="${id}">Remove</button>${S.openRm===id?`<div class="reasons"><span class="xs muted" style="width:100%">Why are you removing one?</span><button class="btn sm ghost" data-why="died" data-id="${id}">It died</button><button class="btn sm ghost" data-why="eaten" data-id="${id}">Eaten or killed</button><button class="btn sm ghost" data-why="removed" data-id="${id}">Rehomed / moved</button></div>`:''}</div>`}).join('');
 const prow=c.pl.map(x=>`<div class="prow">${thumb(x)}<div><b>${esc(x.n)} × ${t.plants[x.id]}</b><div class="xs muted">${POS[x.pos]}</div></div><span></span></div>`).join('');
 const tests=[...t.tests].sort((a,b)=>a.date.localeCompare(b.date));
 V.innerHTML=`<div class="wrap plan fadein" style="padding-bottom:60px"><div>
  <button class="btn sm ghost" data-backtanks>${I('back',15)}All aquariums</button>
  ${S.alert?`<div class="alert" style="margin-top:14px" role="alert"><b style="color:var(--bad)">${esc(S.alert.t)}</b><br>${esc(S.alert.x)}</div>`:''}
  <div style="margin:14px 0"><span class="typeb">${TYPEN[t.type]}</span><h2>${esc(t.name)}</h2></div>
  <div class="panel"><h3 style="margin-bottom:10px">Animals</h3><div style="display:grid;gap:8px">${rows||'<span class="muted">No animals yet.</span>'}</div>${prow?`<h3 style="margin:16px 0 10px">Plants</h3><div style="display:grid;gap:8px">${prow}</div>`:''}</div>
  ${t.type!=='future'?`<div class="panel" style="margin-top:16px"><h3>Water tests</h3>${last?`<div class="wt" style="margin-top:10px">${[['alert','Ammonia',last.ammonia+' ppm',last.ammonia==0],['alert','Nitrite',last.nitrite+' ppm',last.nitrite==0],['layers','Nitrate',last.nitrate+' ppm',last.nitrate<=20],['drop','pH',last.ph,!c.ph||(last.ph>=c.ph[0]&&last.ph<=c.ph[1])],['thermo','Temperature',last.temp+' °C',!c.temp||(last.temp>=c.temp[0]&&last.temp<=c.temp[1])]].map(([ic,l,v,ok])=>statc(ic,ok?'#45D483':'#FF6A57',v,l+(ok?' · OK':' · act now'))).join('')}</div><p class="xs muted">Last test ${fmtD(last.date)}</p>`:'<p class="muted sm">No tests yet. Log your first one below.</p>'}
   ${tests.length>1?chart(tests):''}
   <form id="testform" class="dims" style="margin-top:12px">${[['ft','Temp °C',last?.temp??25,.1],['fp','pH',last?.ph??7,.1],['fa','Ammonia',0,.25],['fi','Nitrite',0,.25],['fn','Nitrate',last?.nitrate??10,1]].map(([id,l,v,s])=>`<label class="field">${l}<input id="${id}" type="number" step="${s}" value="${v}" inputmode="decimal"></label>`).join('')}<button class="btn" style="grid-column:1/-1">${I('drop',18)}Save water test (+10 XP)</button></form></div>`:''}
  ${t.type!=='future'?`<div class="panel" style="margin-top:16px"><h3>Log</h3><div class="logg"><form id="expform"><b class="sm">${I('coins',15)} Expense</b><div class="dims" style="margin-top:6px"><label class="field">Amount (${prefs.cur})<input id="ex_amt" type="number" min="0" step="0.01" inputmode="decimal" required></label><label class="field">What for<input id="ex_note" placeholder="e.g. food, filter"></label></div><button class="btn sm ghost" style="margin-top:8px">${I('plus',15)}Log expense</button></form>
   <form id="brform"><b class="sm">${I('baby',15)} Breeding success</b><div class="dims" style="margin-top:6px"><label class="field">Species<select id="br_sp">${c.ids.map(id=>`<option value="${id}">${esc(BY[id].n)}</option>`).join('')}</select></label><label class="field">Young raised<input id="br_n" type="number" min="1" value="10" inputmode="numeric"></label></div><label class="xs muted" style="display:flex;gap:6px;align-items:center;margin-top:6px"><input id="br_add" type="checkbox" style="accent-color:var(--accent)">Add them to this tank</label><button class="btn sm ghost" style="margin-top:8px" ${c.ids.length?'':'disabled'}>${I('plus',15)}Log breeding</button></form></div>
   ${(t.expenses||[]).length?`<p class="xs muted" style="margin-top:8px">Logged spend on this tank: <b style="color:var(--ink)">${money((t.expenses||[]).reduce((a,e)=>a+e.usd,0))}</b></p>`:''}</div>`:''}
  <div class="panel" style="margin-top:16px"><h3>History</h3>${[...t.events].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8).map(e=>`<div class="ev"><time class="muted xs">${fmtD(e.date)}</time><span class="${e.type==='died'||e.type==='eaten'?'flag':''}">${e.type==='died'||e.type==='eaten'?'⚑ ':''}${esc(e.text)}</span></div>`).join('')||'<p class="muted sm">Nothing yet.</p>'}</div></div>
 <aside class="stickyp"><div class="panel">${tankSvg(t,{h:300})}<div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px">${pill(c.status)}<span class="sm muted">${Math.round(c.v.net)} L · ${c.temp?c.temp.join('–')+' °C':'temp clash'}</span></div>
  <div class="xs muted" style="margin-top:8px">${I('coins',14)} Setup ${mrange(cost.setup)} · monthly ${mrange(cost.monthly)}</div>
  <div style="display:grid;gap:6px;margin-top:10px">${c.items.filter(i=>i.level!=='good').slice(0,4).map(i=>`<div class="issue ${i.level}"><div><b>${esc(i.title)}</b><span class="muted">${esc(i.text)}</span></div></div>`).join('')}</div>
  <div class="ctas" style="margin-top:12px"><button class="btn grad" data-edittank>${I('gear',16)}Edit</button><button class="btn ghost" data-design="${t.id}">${I('move',16)}Design</button>${t.postId?`<button class="btn ghost" data-cshareit="post:${t.postId}">${I('share',16)}Share to social</button>`:''}<button class="btn ghost" data-cpick="${t.id}" data-csheet>${I('image',16)}${t.postId?'Update shared':'Share to community'}</button>${t.type==='future'?`<button class="btn lime" data-setup>${I('check',16,3)}Mark as set up</button>`:''}<button class="btn ghost" data-deltank>${S.del?'Tap again to delete':'Delete'}</button></div></div></aside></div>${footer()}`;
 const ef=$('#expform');if(ef)ef.onsubmit=e=>{e.preventDefault();const amt=+$('#ex_amt').value;if(!(amt>0))return;const rate=(CURR[prefs.cur]||CURR.USD)[1];(t.expenses=t.expenses||[]).push({date:iso(today),usd:amt/rate,note:$('#ex_note').value.trim()});t.events.push({date:iso(today),type:'expense',text:`Spent ${money(amt/rate)}${$('#ex_note').value.trim()?' on '+$('#ex_note').value.trim():''}`});saveTanks();xp(5,'Expense logged');render()};
 const bf=$('#brform');if(bf)bf.onsubmit=e=>{e.preventDefault();const id=$('#br_sp').value,n=Math.max(1,+$('#br_n').value||1);t.events.push({date:iso(today),type:'bred',qty:n,text:`${n} young ${BY[id].n} raised`});if($('#br_add').checked){const f=t.fish[id];syncF(f);f.groups.push({n,size:BY[id].sized?0:undefined,v:f.groups[0]?f.groups[0].v:undefined});syncF(f)}saveTanks();xp(25,'Breeding success');award('breeder');render()};
 const tf=$('#testform');if(tf)tf.onsubmit=e=>{e.preventDefault();const g=id=>+$('#'+id).value;const v={temp:g('ft'),ph:g('fp'),ammonia:g('fa'),nitrite:g('fi'),nitrate:g('fn')};const bad=v.temp<0||v.temp>40?'Temperature should be between 0 and 40 °C':v.ph<3||v.ph>10.5?'pH should be between 3 and 10.5':v.ammonia<0||v.ammonia>20||v.nitrite<0||v.nitrite>20||v.nitrate<0||v.nitrate>500?'Check the ammonia, nitrite and nitrate values':'';if(bad){toast(bad);return}const lt=t.tests[t.tests.length-1];if(lt&&lt.date===iso(today)&&['temp','ph','ammonia','nitrite','nitrate'].every(k=>+lt[k]===v[k])){toast('This exact test is already logged for today.');return}const firstToday=!t.tests.some(x=>x.date===iso(today));t.__noxp=!firstToday;t.tests.push({date:iso(today),temp:g('ft'),ph:g('fp'),ammonia:g('fa'),nitrite:g('fi'),nitrate:g('fn')});
  if(g('fa')>0||g('fi')>0)S.alert={t:'Red alert: ammonia or nitrite detected',x:'Do a 30–50% water change today, dose a water conditioner and feed lightly until both read 0.'};saveTanks();if(!t.__noxp){xp(10,'Water test');qInc('test')}else toast('Test saved');delete t.__noxp;if(stat('tests')>=5)award('tester');render()}}
function chart(tests){const W=520,H=150,l=30,r=12,tp=14,b=24,vals=tests.map(x=>+x.nitrate),mx=Math.max(32,...vals)*1.1;const X=i=>l+i*(W-l-r)/(tests.length-1),Y=v=>tp+(1-v/mx)*(H-tp-b);const pts=vals.map((v,i)=>`${X(i)},${Y(v)}`).join(' '),li=vals.length-1;
 return `<div class="lbl">Nitrate over time (ppm)</div><svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Nitrate over time">${[0,10,20,30].filter(v=>v<mx).map(v=>`<line x1="${l}" x2="${W-r}" y1="${Y(v)}" y2="${Y(v)}" stroke="var(--line)"/><text x="${l-6}" y="${Y(v)+4}" text-anchor="end" font-size="10" fill="var(--muted)">${v}</text>`).join('')}<line x1="${l}" x2="${W-r}" y1="${Y(20)}" y2="${Y(20)}" stroke="var(--bad)" stroke-dasharray="4 4"/><text x="${W-r}" y="${Y(20)-5}" text-anchor="end" font-size="10" fill="var(--bad)">limit 20</text><polygon points="${X(0)},${Y(0)} ${pts} ${X(li)},${Y(0)}" fill="var(--accent)" opacity=".14"/><polyline points="${pts}" fill="none" stroke="var(--accent)" stroke-width="2.4"/><circle cx="${X(li)}" cy="${Y(vals[li])}" r="5" fill="${vals[li]>20?'var(--bad)':'var(--accent)'}" stroke="var(--bg)" stroke-width="2"/><text x="${l}" y="${H-6}" font-size="10" fill="var(--muted)">${fmtD(tests[0].date)}</text><text x="${W-r}" y="${H-6}" text-anchor="end" font-size="10" fill="var(--muted)">${fmtD(tests[li].date)}</text></svg>`}
function demoTanks(){const a=tplTank(TB.community_60||TEMPLATES[0],'existing');a.id='demo1';a.name='Living room community';const nit=[8,11,14,18,23,12,15,18];a.tests=nit.map((x,i)=>({date:iso(+today-(7*(7-i)+2)*DAY),nitrate:x,temp:25.5,ph:7,ammonia:i===4?.25:0,nitrite:0}));a.events=[{date:iso(+today-55*DAY),type:'added',text:'Tank set up'}];
 const b=tplTank(TB.oscar||TEMPLATES[0],'future');b.id='demo2';b.name='Oscar dream tank';b.fish={oscar:{n:2,groups:[{n:1,size:0,v:0},{n:1,size:1,v:2}]},guppy:{n:5,groups:[{n:5}]}};[b.L,b.W,b.H]=[60,30,36];return[a,b]}

