  if(d.dall!==undefined){t.layout={};S.dSel=null;dSave(t);SFX('water');renderDesigner($('#modal'));return}
  if(d.drm){const k=d.drm;if(k.startsWith('pl:')){const pid=k.split(':')[1];t.plants[pid]--;if(t.plants[pid]<=0)delete t.plants[pid];Object.keys(t.layout).filter(x=>x.startsWith('pl:'+pid+':')).forEach(x=>delete t.layout[x])}else if(k==='wood')t.eq.wood=false;else if(k==='cave')t.eq.cave=false;else if(k.startsWith('rock'))t.eq.rocks=false;delete t.layout[k];S.dSel=null;SFX('remove');dSave(t);renderDesigner($('#modal'));return}
