 if(d.scan!==undefined){S.modal=[];openSheet('scan');return}
 if(d.go){if(d.go==='tanks'){S.openTank=null}if(d.go==='explore'&&d.main===undefined&&d.sub===undefined){S.sub=null;S.q=''}go(d.go);return}
 if(d.open){S.sheet=null;bumpView(d.open);window.__disc&&window.__disc(d.open);if(BY[d.open]?.kind==='sp'&&!game.seen.includes(d.open)){game.seen.push(d.open);saveGame();if(game.seen.length>=25)award('explorer')}S.modal.push(d.open);renderModal();return}
 if(d.main!==undefined){S.main=d.main||null;S.sub=null;S.q='';S.care=0;S.tm='';go('explore');return}
 if(d.sub!==undefined){S.sub=d.sub||null;vExplore();return}
 if(d.care){S.care=S.care===+d.care?0:+d.care;vExplore();return}
