 if(d.ccopy){const p=postBy(d.ccopy);if(p)copySetup(p);return}
 if(d.cshareurl){const url=location.href.split('#')[0]+'#post='+d.cshareurl;const p=postBy(d.cshareurl);if(navigator.share)navigator.share({title:p?p.name:'Aquarium',text:'Check out this aquarium on FishMate',url}).catch(()=>{});else{try{navigator.clipboard.writeText(url);toast(`${I('check',16)} Link copied`)}catch(_){toast(url)}}return}
 if(d.cunshare){if(!S.cmDel){S.cmDel=true;toast('Tap Remove again to take it down');setTimeout(()=>S.cmDel=false,3000);return}CMD.posts=CMD.posts.filter(p=>p.id!==d.cunshare);S.tanks.forEach(t=>{if(t.postId===d.cunshare)delete t.postId});saveTanks();cmSave();S.cm.post=null;S.cmDel=false;render();toast('Removed from the community');return}
