function rateOf(p){const mine=CMD.ratings[p.id]||0,sum=(p.rsum||0)+mine,cnt=(p.rcount||0)+(mine?1:0);return{avg:cnt?sum/cnt:0,cnt,mine}}
function starsRow(avg,sz=14){return `<span class="stars5" style="--sz:${sz}px">${[1,2,3,4,5].map(i=>{const f=Math.max(0,Math.min(1,avg-i+1));return `<i style="--f:${Math.round(f*100)}%">★</i>`}).join('')}</span>`}
function rateBadge(p){const r=rateOf(p);return r.cnt?`<span class="prate">${starsRow(r.avg,12)}<b>${r.avg.toFixed(1)}</b><em>(${r.cnt})</em></span>`:`<span class="prate new">${I('star',12)}Not rated yet</span>`}

