let _names=null;function nameIdx(){if(_names)return _names;_names=[];ALL.forEach(x=>{if(!['sp','pl'].includes(x.kind))return;[x.n,...(x.aka||[])].forEach(n=>{n=String(n).toLowerCase().replace(/\s*\(.*?\)\s*/g,' ').trim();if(n.length>=3)_names.push([n,x.id])})});_names.sort((a,b)=>b[0].length-a[0].length);return _names}
function findItems(t){t=' '+t.toLowerCase().replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ')+' ';const out=[];for(const [n,id] of nameIdx()){const k=' '+n.replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ')+' ';const ks=k.replace(/s $/,' ');if((t.includes(k)||t.includes(ks.trimEnd()+'s ')||(k.length>6&&t.includes(ks)))&&!out.includes(id)){out.push(id);t=t.replace(k,' ')}if(out.length>=3)break}return out.map(id=>BY[id])}
const chipOf=x=>`<button class="hchip" data-open="${x.id}">${thumb(x)}<span>${esc(x.n)}</span></button>`;
function finnReply(q){const t=q.toLowerCase(),xs=findItems(q),sp=xs.filter(x=>x.kind==='sp');const L=(t.match(/(\d{2,4})\s*(l|litre|liter|ltr)/)||[])[1];
 if(sp.length>=2){const [a,b]=sp,r=pairScore(a,b);const v={good:'Yes 👍',ok:'With care ⚠️',bad:'Not a good idea ❌'}[r.lvl]||r.lvl;return `<b>${esc(a.n)} + ${esc(b.n)}: ${v}</b> (${r.score}/100)<br>${r.why.slice(0,3).map(w=>'• '+esc(w[1])).join('<br>')}<div class="hchips">${chipOf(a)}${chipOf(b)}<button class="hchip" data-hcmp="${a.id},${b.id}">${I('vs',14)}<span>Full comparison</span></button></div>`}
 if(sp.length===1){const x=sp[0];
  if(/tank|size|litre|liter|gallon|how big|space/.test(t))return `${/^[aeiou]/i.test(x.n)?'An':'A'} <b>${esc(x.n)}</b> needs at least <b>${x.minL} L</b> (${galL(x.minL)} gal). It grows to ${x.cm} cm.<div class="hchips">${chipOf(x)}</div>`;
  if(/temp|heat|warm|cold|degree/.test(t))return `<b>${esc(x.n)}</b>: ${x.t.join('–')} °C is ideal.<div class="hchips">${chipOf(x)}</div>`;
  if(/\bph\b|acid|alkal|hard|soft/.test(t))return `<b>${esc(x.n)}</b>: pH ${x.ph.join('–')}.<div class="hchips">${chipOf(x)}</div>`;
  if(/eat|food|feed|diet/.test(t))return `<b>${esc(x.n)}</b> (${DIET[x.diet].toLowerCase()}): ${esc(x.food)}<div class="hchips">${chipOf(x)}</div>`;
  if(/male|female|sex|gender/.test(t)&&x.sex)return `<b>${esc(x.n)}</b><br>♂ ${esc(x.sex.m)}<br>♀ ${esc(x.sex.f)}<div class="hchips">${chipOf(x)}</div>`;
  if(/how many|group|school|alone|together/.test(t))return `<b>${esc(x.n)}</b>: ${x.grp>1?`keep ${x.grp} or more together.`:'best kept on its own.'}<div class="hchips">${chipOf(x)}</div>`;
  if(/with|tankmate|live|mates|compatible/.test(t)){const good=SP.filter(y=>y.id!==x.id).map(y=>[y,pairScore(x,y)]).filter(o=>o[1].lvl==='good').sort((a,b)=>b[1].score-a[1].score).slice(0,6).map(o=>o[0]);return `Great tankmates for <b>${esc(x.n)}</b>:<div class="hchips">${good.map(chipOf).join('')}</div>`}
  return `<b>${esc(x.n)}</b> · ${CARE[x.care]} · ${TM[x.tm]}<br>Adult ${x.cm} cm · tank ${x.minL} L+ · ${x.t.join('–')} °C · pH ${x.ph.join('–')} · ${x.grp>1?'groups of '+x.grp+'+':'single'}<div class="hchips">${chipOf(x)}</div>`}
 if(xs.length)return `Here’s what I found:<div class="hchips">${xs.map(chipOf).join('')}</div>`;
 if(L){const n=+L;const pick=SP.filter(x=>x.main==='fish'&&x.minL<=n&&x.care===1&&x.tm==='p').sort(()=>Math.random()-.5).slice(0,6);return `Easy, peaceful fish that fit <b>${n} L</b>:<div class="hchips">${pick.map(chipOf).join('')}</div><span class="xs muted">Tip: open the planner to check the full stocking.</span>`}
 if(/beginner|easy|first|start/.test(t)){const pick=SP.filter(x=>x.main==='fish'&&x.care===1&&x.tm==='p').slice(0,6);return `Good first fish:<div class="hchips">${pick.map(chipOf).join('')}</div>`}
 const dz=search(q,ALL.filter(x=>x.main==='diseases')).slice(0,3);if(dz.length&&/spot|sick|disease|white|fungus|rot|ill|dying|lazy|swim|bloat/.test(t))return `This might be:<div class="hchips">${dz.map(chipOf).join('')}</div><span class="xs muted">Check water first: ammonia, nitrite and temperature.</span>`;
 const r=search(q).slice(0,4);if(r.length)return `Maybe one of these?<div class="hchips">${r.map(chipOf).join('')}</div>`;
 return `I’m a small fish helper 🐟 Try: <i>“Can neon live with betta?”</i>, <i>“tank size for angelfish”</i> or <i>“fish for 60 L”</i>.`}
