function projTank(p){const t=newTank('future');Object.assign(t,{id:'pj-'+p.id,name:p.name,unit:'cm',shape:'rect',W:30,H:36,L:Math.max(20,Math.round(p.L*1000/(30*36*0.88)))});p.items.filter(i=>score(i)>=0).forEach(i=>{const x=BY[i.id];if(!x)return;if(x.kind==='sp')t.fish[x.id]={n:i.n||x.grp||1};else if(x.kind==='pl')t.plants[x.id]=i.n||1});return t}
