const qRank=(v=game.quiz.best)=>{let i=0;QRANK.forEach((r,k)=>{if(v>=r[0])i=k});const nx=QRANK[i+1];return{i,r:QRANK[i],next:nx,pct:nx?(v-QRANK[i][0])/(nx[0]-QRANK[i][0]):1}};
