let rs=Math.random;const pick=a=>a[Math.floor(rs()*a.length)];const shuffle=a=>a.map(v=>[rs(),v]).sort((x,y)=>x[0]-y[0]).map(v=>v[1]);
function mkRng(seed){let s=seed%2147483647;if(s<=0)s+=2147483646;return()=>(s=s*16807%2147483647)/2147483647}
function genQ(mode){const P=QP();const types=mode==='daily'?['compat','compat','name','bigger','tank']:['compat','compat','name','bigger','warmer','tank','name'];const t=pick(types);
 if(t==='compat'){for(let k=0;k<20;k++){const a=pick(P),b=pick(P);if(a.id===b.id)continue;const r=pairCheck(a,b);return{t,a:a.id,b:b.id,ans:r.lvl,why:r.why[0]?r.why[0][1]:'',q:'Can they live together?',opts:[['good','Yes','check','#16A34A'],['warn','With care','alert','#D97706'],['bad','No','x','#DC2626']]}}}
 if(t==='bigger'){for(let k=0;k<20;k++){const a=pick(P),b=pick(P);if(a.id===b.id||Math.abs(a.cm-b.cm)<2)continue;return{t,a:a.id,b:b.id,ans:a.cm>b.cm?a.id:b.id,why:`${a.n} grows to ${a.cm} cm, ${b.n} to ${b.cm} cm.`,q:'Which one grows bigger?',pickFish:1}}}
 if(t==='warmer'){for(let k=0;k<20;k++){const a=pick(P),b=pick(P);const ma=(a.t[0]+a.t[1])/2,mb=(b.t[0]+b.t[1])/2;if(a.id===b.id||Math.abs(ma-mb)<3)continue;return{t,a:a.id,b:b.id,ans:ma>mb?a.id:b.id,why:`${a.n}: ${a.t.join('–')} °C · ${b.n}: ${b.t.join('–')} °C.`,q:'Which one needs warmer water?',pickFish:1}}}
 if(t==='name'){const a=pick(P);const others=shuffle(P.filter(x=>x.id!==a.id&&x.cat===a.cat)).slice(0,3);const fill=shuffle(P.filter(x=>x.id!==a.id&&!others.includes(x))).slice(0,3-others.length);const opts=shuffle([a,...others,...fill]).map(x=>[x.id,x.n]);return{t,a:a.id,ans:a.id,why:`That’s the ${a.n}${a.sci?' ('+a.sci+')':''}.`,q:'What fish is this?',opts}}
 if(t==='tank'){const a=pick(P);const v=a.minL;const set=new Set([v]);const cand=[20,40,60,80,100,150,200,250,300,400,500,800,1000].filter(x=>x!==v);while(set.size<4)set.add(pick(cand));const opts=shuffle([...set]).map(x=>[String(x),x+' L']);return{t,a:a.id,ans:String(v),why:`${a.n} needs at least ${v} L (${galL(v)} gal).`,q:`Smallest tank for one group of ${a.n}?`,opts}}
 return genQ(mode)}
