const NFT_R={l:['Legendary','#F59E0B','#F472B6'],e:['Epic','#A78BFA','#22D3EE'],r:['Rare','#38BDF8','#22C55E'],c:['Common','#94A3B8','#CBD5E1']};
const NFT_L=['builder3','qs10000','xp5000','patron','teambuild','challenger','discx'],NFT_E=['reefsaint','dreambuilt','photog','qs6000','xp2500','qcombo','qspeed','breeder','generous','collector','scout','creator','doctor','mguess5','tester','nano','helper'],NFT_RR=['kindfin','qs3000','xp1000','quiz5','planted','explorer','match10','qperfect','chatty','critic','fishcritic','plantcritic','gearguru','complete','megaphone','qs1000','xp500','gift1','verified','daily','designer'];
const nftRar=id=>NFT_L.includes(id)?'l':NFT_E.includes(id)?'e':NFT_RR.includes(id)?'r':'c';
const nftHash=s=>{let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return h>>>0};
function nftArt(b,on){const h=nftHash(b[0]),c1=b[4],c2=b[5],pat=h%4,gid='ng'+b[0];let deco='';
 if(pat===0)deco=[0,1,2,3,4].map(i=>`<circle cx="60" cy="60" r="${18+i*11}" fill="none" stroke="#fff" stroke-opacity="${.16-i*.025}" stroke-width="1.5"/>`).join('');
 else if(pat===1)deco=Array.from({length:16},(_,i)=>`<path d="M60 60 L${60+70*Math.cos(i*Math.PI/8)} ${60+70*Math.sin(i*Math.PI/8)}" stroke="#fff" stroke-opacity=".12" stroke-width="${i%2?3:7}"/>`).join('');
 else if(pat===2)deco=Array.from({length:30},(_,i)=>{const x=(nftHash(b[0]+i)%120),y=(nftHash(i+b[0])%120),r=1+(nftHash('r'+i+b[0])%3);return `<circle cx="${x}" cy="${y}" r="${r}" fill="#fff" fill-opacity=".35"/>`}).join('');
 else deco=Array.from({length:6},(_,i)=>`<path d="M-10 ${30+i*16} Q30 ${20+i*16} 60 ${30+i*16} T130 ${30+i*16}" fill="none" stroke="#fff" stroke-opacity=".14" stroke-width="3"/>`).join('');
 const shape=['M60 14 L100 37 L100 83 L60 106 L20 83 L20 37Z','M60 12 C88 12 104 24 104 24 L100 70 C96 92 60 108 60 108 C60 108 24 92 20 70 L16 24 C16 24 32 12 60 12Z','M60 10 L72 44 L108 46 L80 68 L90 104 L60 84 L30 104 L40 68 L12 46 L48 44Z','M60 14 A46 46 0 1 1 59.9 14Z'][h%4];
 return `<svg class="nftsvg" viewBox="0 0 120 120" aria-hidden="true"><defs><radialGradient id="${gid}b" cx="35%" cy="25%" r="90%"><stop offset="0" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/></radialGradient><linearGradient id="${gid}s" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".9"/><stop offset=".5" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/></linearGradient></defs>
 <rect width="120" height="120" fill="url(#${gid}b)"/>${deco}<path d="${shape}" fill="rgba(0,0,0,.28)" transform="translate(0 4)"/><path d="${shape}" fill="url(#${gid}s)" stroke="#fff" stroke-opacity=".7" stroke-width="2"/><path d="${shape}" fill="none" stroke="rgba(0,0,0,.25)" stroke-width="6" transform="scale(.8) translate(15 15)"/></svg>
 <span class="nfticon">${I(b[3],38)}</span>`}
function nftCard(b){const on=game.badges.includes(b[0]),r=nftRar(b[0]),R=NFT_R[r],ser=String(nftHash(b[0])%9000+1000);
 return `<div class="nft r-${r} ${on?'on':'off'}" style="--n1:${R[1]};--n2:${R[2]};--c1:${b[4]};--c2:${b[5]}" title="${esc(b[2])}"><div class="nftin"><div class="nftart">${nftArt(b,on)}<span class="nftholo"></span><span class="nftrar">${R[0]}</span>${on?'':'<span class="nftlock">Locked</span>'}</div><div class="nftmeta"><b>${esc(b[1])}</b><small>${esc(b[2])}</small><span class="nftser">#${ser} · ${on?'Owned':'Not owned'}</span></div></div></div>`}
