try{
/* Typical male/female differences by group. Row keys: size, body, colour, fins, head, belly, vent, behav, age */
const FAM={
 'Tetras':{size:['Slightly smaller','Slightly larger, especially when full of eggs'],body:['Slim, straight belly line','Deeper, rounder belly (look from above)'],colour:['Brighter, stronger colour in mature fish','A little paler'],fins:['Anal fin may be straighter; some species have tiny hooks on it','Plain fins'],behav:['Display to each other with spread fins','Chased by males at spawning time'],age:'From about 4 to 6 months, best in a group'},
 'Barbs':{size:['Smaller, slimmer','Larger and heavier'],body:['Slim and streamlined','Rounder, fuller belly'],colour:['Brighter; red nose or fins in breeding colour','Duller, more washed-out'],fins:['Brighter fin edges','Plainer fins'],behav:['Chase and display, more active','Calmer, often feeding'],age:'From about 4 months'},
 'Danios & Rasboras':{size:['Slightly smaller','Slightly larger'],body:['Slender, torpedo-shaped','Fuller, rounder belly'],colour:['More golden or vivid tones','Paler, more silver'],fins:['Brighter fin colour','Plainer fins'],behav:['Males chase females and spar with each other','Lead the chase when ready to spawn'],age:'From about 3 to 4 months'},
 'Livebearers':{size:['Smaller','Clearly larger'],body:['Slim','Round belly, bigger when pregnant'],colour:['Usually much more colourful','Usually plainer'],fins:['Anal fin turns into a rod (gonopodium) for mating','Normal fan-shaped anal fin'],belly:['No spot','Dark gravid spot behind the belly when pregnant'],behav:['Constantly follows females','Gives birth to live fry every 4 to 6 weeks'],age:'From about 6 to 8 weeks (gonopodium appears)'},
 'Gouramis & Bettas':{size:['Often a little larger','Often a little smaller'],body:['Slimmer','Rounder, white egg spot on some species'],colour:['Much brighter, especially when nesting','Duller with stripes or bars'],fins:['Longer, pointed dorsal and flowing fins','Shorter, rounded fins'],belly:['No egg spot','Small white egg spot (ovipositor) behind the belly fins'],behav:['Builds a bubble nest at the surface','Inspects the nest when ready'],age:'From about 3 to 4 months'},
 'Cichlids':{size:['Usually larger','Usually smaller'],body:['Bigger head, sometimes a hump','Rounder belly'],colour:['Brighter, more intense colours','Duller; some show breeding colours'],fins:['Longer, pointed dorsal and anal fin tips','Shorter, rounder fins'],vent:['Thin, pointed breeding tube','Wide, blunt breeding tube'],behav:['Defends territory, digs and displays','Cleans a flat stone or cave before spawning'],age:'From about 4 to 6 months; the breeding tube shows only when spawning'},
 'African Cichlids':{size:['Usually larger','Smaller'],body:['Larger head, sometimes a hump','Rounder'],colour:['Bright display colours (blue, yellow, orange)','Often plainer brown-grey or barred'],fins:['Egg spots on the anal fin; longer fin tips','Fewer or no egg spots'],vent:['Pointed breeding tube','Blunt breeding tube'],behav:['Holds territory and shakes at females','Holds eggs in her mouth (mouthbrooder)'],age:'From about 6 months; colour shows first in males'},
 'Catfish & Plecos':{size:['Often a little smaller','Often larger and wider'],body:['Slimmer, flatter belly','Wider and rounder seen from above'],fins:['Larger, thicker first pectoral spine','Shorter, thinner pectoral fins'],head:['More bristles or odontodes (plecos)','Few or no bristles'],behav:['Guards a cave and the eggs (plecos)','Visits the male’s cave to lay eggs'],age:'From about 6 to 12 months'},
 'Loaches':{size:['Usually smaller','Usually larger'],body:['Slimmer','Rounder belly'],fins:['Larger or thicker pectoral fins in some species','Smaller pectoral fins'],behav:['Spars with other males','Calmer'],age:'Adults only, often hard to tell'},
 'Algae Eaters':{size:['Similar or smaller','Similar or larger'],body:['Slimmer','Rounder belly'],head:['Breeding bumps on the snout in some species','Smooth snout'],behav:['More territorial','Less territorial'],age:'Adults only'},
 'Rainbowfish':{size:['Larger','Smaller'],body:['Deeper, higher back','Slimmer'],colour:['Much brighter; flashes colour when displaying','Plainer, silvery'],fins:['Longer dorsal and anal fins with coloured edges','Shorter, clearer fins'],behav:['Displays a bright stripe on the forehead at dawn','Lays eggs on fine plants'],age:'From about 4 to 6 months'},
 'Killifish':{size:['Similar','Similar'],body:['Slim','Rounder'],colour:['Very colourful with patterns','Plain brown or beige'],fins:['Large, colourful, often pointed fins','Small, rounded, clear fins'],behav:['Displays constantly','Lays eggs in moss or peat'],age:'From about 2 to 3 months'},
 'Gobies & Sleepers':{body:['Larger head, slimmer body','Rounder belly'],colour:['Brighter colours and fin edges','Plainer'],fins:['Longer first dorsal fin','Shorter fins'],behav:['Guards a cave','Lays eggs on the cave roof'],age:'Adults'},
 'Puffers':{colour:['Darker or stronger markings','Lighter, plainer'],body:['Often a wrinkle or ridge behind the eye','Rounder'],belly:['Coloured belly line in some species','Plain belly'],behav:['Courts and chases','Picks the spawning spot'],age:'Adults; many species cannot be sexed by eye'},
 'Goldfish & Coldwater':{body:['Slimmer, streamlined','Rounder, lopsided belly when full of eggs'],head:['White breeding stars (tubercles) on gill covers in spring','No breeding stars'],fins:['Breeding stars on the front edge of the pectoral fins','Smooth pectoral fins'],vent:['Narrow, oval vent','Rounder, protruding vent'],behav:['Chases females in spring','Gets chased'],age:'From about 1 year, in spring'},
 'Oddballs & Predators':{size:['Often smaller','Often larger'],body:['Slimmer','Rounder'],behav:['Varies by species','Varies by species'],age:'Usually adults only; many cannot be sexed by eye'},
 'Shrimp':{size:['Smaller','Larger'],body:['Slim, straight underside','Curved, wider tail section to carry eggs'],colour:['Often paler or clearer','Stronger colour'],belly:['No eggs','Carries eggs under the tail; egg “saddle” behind the head'],behav:['Swims around looking for females after a molt','Releases a scent after molting'],age:'From about 2 to 3 months'},
 'Crayfish & Crabs':{size:['Often larger claws','Smaller claws'],body:['Narrow belly flap (crabs)','Wide, round belly flap (crabs)'],vent:['Hard hooks on the first swimmerets (crayfish)','Soft swimmerets; carries eggs under the tail'],behav:['More aggressive','Hides when carrying eggs'],age:'From about 3 to 6 months'},
 'Snails':{body:['Many species: no visible difference','Lays eggs (where each species lays differs)'],behav:['Some snails (ramshorn, bladder) are both sexes at once','Egg-laying spot depends on the species'],age:'Usually only by watching eggs or mating'},
 'Frogs & Newts':{size:['Smaller','Larger, wider'],body:['Slimmer; swollen vent in breeding season (newts)','Rounder, pear-shaped'],head:['Glands behind the front legs or dark nuptial pads (frogs)','No glands or pads'],behav:['Calls or displays in breeding season','Lays eggs on plants'],age:'Adults, mostly in breeding season'},
 'Axolotls':{size:['Similar','Wider body'],body:['Slimmer','Rounder when full of eggs'],vent:['Swollen cloaca behind the back legs','Flat cloaca'],age:'From about 12 months'},
 'Turtles':{size:['Usually smaller','Usually larger'],fins:['Long front claws (many species)','Short claws'],vent:['Long, thick tail; vent past the shell edge','Short tail; vent under the shell'],body:['Concave belly shell (some species)','Flat belly shell'],age:'From about 1 to 3 years'},
 'Clams & Other Invertebrates':{body:['No visible difference','No visible difference'],age:'Not possible by eye'}};
const ROWS=[['size','Size','ruler'],['body','Body shape','fish'],['colour','Colour','palette'],['fins','Fins','layers'],['head','Head','eye'],['belly','Belly & eggs','egg'],['vent','Breeding tube / vent','target'],['behav','Behaviour','users']];
const KW={size:/\b(larg|small|big|size|tiny|grows)/i,body:/\b(slim|round|deep|belly|body|plump|full|thin|slender|wide|back|shape)/i,colour:/\b(colou?r|bright|red\b|blue|orange|yellow|gold|green|pale|dull|plain|vivid|silver|brown|stripe|spot|black|dark|pink|white|neon|sparkl|metallic|bars?\b|scales)/i,fins:/\b(fin|fins|dorsal|anal|tail\b|tail lobes|gonopod|claw|pectoral|spine|ventral)/i,head:/\b(head|hump|eye|snout|forehead|bristle|odontode|tubercle|star|lips?|jaw|tentacle|gland|chin)/i,belly:/\b(egg|gravid|saddle|pregnan|berried|belly)/i,vent:/\b(tube|vent\b|cloaca|papilla|ovipositor|flap|swimmeret)/i,behav:/\b(nest|guard|display|chase|call|spawn|carr|lays?|brood)/i};
const DIFF={1:['Easy','#22C55E'],2:['Takes practice','#F59E0B'],3:['Hard','#EF4444']};
const parts=t=>String(t||'').split(/;\s*|\.\s+|,\s+(?=[a-z])/).map(v=>v.trim().replace(/\.$/,'')).filter(v=>v.length>2);
const cap=s=>s?s[0].toUpperCase()+s.slice(1):s;
function rowsFor(x){const fam=FAM[x.cat]||{},PRI=['vent','belly','head','fins','colour','body','size','behav'];
 const assign=arr=>{const o={};arr.forEach(p=>{const k=PRI.find(k=>KW[k].test(p));if(k)(o[k]=o[k]||[]).push(p);else(o.body=o.body||[]).push(p)});return o};
 if(/\b(looks? (the )?same|look alike|no (reliable |clear )?(visible|external) difference|cannot be sexed|can't be sexed|not possible by eye|hermaphrodite)/i.test(x.sex.m+' '+x.sex.f))return [];const A=assign(parts(x.sex.m)),B=assign(parts(x.sex.f)),out=[];
 for(const [k,l,ic] of ROWS){let mv=(A[k]||[]).join('; '),fv=(B[k]||[]).join('; '),src='sp';
  if(!mv&&!fv)continue;if(!mv)mv='No clear difference';if(!fv)fv='No clear difference'
  out.push({k,l,ic,m:cap(mv),f:cap(fv),src})}
 return out}
const MARK={size:null,body:[62,56],colour:[36,40],fins:[30,20],head:[82,42],belly:[54,76],vent:[42,80],behav:null};
function marks(rows){return '';/* fixed-position markers could point at the wrong body part on a real drawing, so they are off */let n=0;return rows.map(r=>{const p=MARK[r.k];if(!p)return '';n++;return `<span class="sxmk" style="left:${p[0]}%;top:${p[1]}%" title="${esc(r.l)}">${rows.indexOf(r)+1}</span>`}).join('')}
const _sbT=sexBlock;sexBlock=function(x,c1,c2){let h=_sbT.apply(this,arguments);try{if(!x.sex)return h;const rows=rowsFor(x);if(rows.length<2)return h;
 /* numbered markers on both pictures */
 const mk=marks(rows);h=h.replace(/<div class="sximg">/g,`<div class="sximg">${mk}`);
 const d=DIFF[x.sex.d]||DIFF[2],fam=FAM[x.cat]||{},anyFam=rows.some(r=>r.src==='fam'||/\*$/.test(r.m)||/\*$/.test(r.f));
 const clean=s=>esc(s.replace(/\*$/,''))+(/\*$/.test(s)?'<sup>*</sup>':'');
 h+=`<div class="sxtab"><div class="sxth"><b>${I('eye',16)} Spot the difference</b><span class="sxdiff" style="--dc:${d[1]}">${d[0]}</span></div>
 <div class="sxtrow sxthead"><span></span><span class="m">♂ Male</span><span class="f">♀ Female</span></div>
 ${rows.map((r,i)=>`<div class="sxtrow"><span class="sxtk"><em>${i+1}</em>${I(r.ic,14)}${r.l}</span><span class="m">${clean(r.m)}</span><span class="f">${clean(r.f)}</span></div>`).join('')}
 <div class="sxtips">${x.sex.tip?`<div>${I('bulb',15)}<span><b>Quickest check:</b> ${esc(x.sex.tip)}</span></div>`:''}${fam.age?`<div>${I('clock',15)}<span><b>When you can tell:</b> ${esc(fam.age)}</span></div>`:''}<div>${I('users',15)}<span><b>Best way:</b> compare several fish side by side, from the side and from above, after feeding.</span></div></div>
 ${anyFam?`<p class="xs muted" style="margin:8px 0 0"><sup>*</sup> Typical for ${esc(x.cat.toLowerCase())}; individual fish vary.</p>`:''}</div>`}catch(e){console.warn('sxt',e)}return h};
window.__sxtReady=true;
}catch(e){console.warn('sxt',e)}
