 sara_shrimps:[{type:'tip',title:'Feed shrimp only what they clear in 2 hours',summary:'Overfeeding is the No. 1 shrimp killer. Small portions keep the water clean and the colony breeding.',species:['cherry'],body:'Give a pinch of food the size of a few shrimp heads. Remove anything left after 2 hours. Skip one day a week — a mature tank with biofilm feeds them anyway.'},
  {type:'breeding',title:'Cherry shrimp: from 10 to 100 in four months',summary:'Stable water, lots of moss and no fish. That is the whole secret.',species:['cherry'],body:'I kept 10 adults in a 30 L planted tank at 24 °C, pH 7.2, GH 7. Berried females appeared after 3 weeks; eggs hatch in about 30 days. Shrimplets hide in moss, so I never use a bare tank.',lessons:'Drip-acclimate new shrimp for at least an hour. Never use copper medicines in a shrimp tank.'}],
 karim_scapes:[{type:'tip',title:'Trim carpet plants little and often',summary:'Cutting a thick carpet in one go makes it lift and rot. Trim a third at a time.',species:[],body:'Use curved scissors and trim every 2–3 weeks. Siphon the clippings straight away so they do not rot and feed algae.'},
  {type:'experience',title:'Why my Iwagumi got green dust algae',summary:'Too much light in the first month, too few plants. How I fixed it without chemicals.',species:[],body:'I ran 8 hours of strong light on a freshly planted carpet. Green spots covered the glass within 10 days.',lessons:'Start with 6 hours of light, plant densely from day one and do 50% water changes twice a week for the first month.'}],
 lina_bettas:[{type:'tip',title:'Bettas jump: always keep a lid',summary:'A gap of a few centimetres is enough for a betta to jump out at night.',species:['betta'],body:'Keep the water level 3–5 cm below the rim and use a lid or floating plants. Bettas also like to breathe at the surface, so leave an air gap under the lid.'},
  {type:'cure',title:'How I cleared mild fin rot in my betta',summary:'Clean, warm water fixed it in two weeks, without antibiotics.',species:['betta'],body:'Ragged fin edges, no fuzz. I did 30% water changes every 2 days, kept 27 °C and removed sharp decor.',lessons:'If the rot reaches the body or turns fuzzy, ask a vet or experienced keeper about medication.'}],
