 mei_axolotl:[{type:'tip',title:'Keep axolotls below 20 °C',summary:'Warm water stresses axolotls and causes infections. A fan or chiller is a must in hot climates.',species:['axolotl'],body:'Aim for 15–18 °C. A clip-on fan over open water lowers it 2–3 °C. Use sand or a bare bottom — gravel can be swallowed and block the gut.'}],
