const FP=window.AVOLDFP||[],AV=window.AVIMG||[];const swap=ph=>{if(typeof ph!=='string'||!/^data:image\/webp/.test(ph))return null;const i=FP.indexOf(ph.slice(200,260));return i>=0&&AV[i]?AV[i]:null};
const u=me();if(u){const n=swap(u.photo);if(n){u.photo=n;try{cmSave()}catch(_){}}}
Object.values((CMD&&CMD.users)||{}).forEach(x=>{const n=swap(x&&x.photo);if(n)x.photo=n});
