try{
/* Mobile header (Borna 4 Oct): only the profile picture + an arrow are shown. The arrow slides the other
   buttons out; tapping any of them runs it and folds the tray again. Unread counts stay visible on the arrow. */
let trayOpen=false;const MQ=matchMedia('(max-width:640px)');
const ARR='<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M15 6l-6 6 6 6"/></svg>';
function unread(tray){let n=0;tray.querySelectorAll('.dot').forEach(d=>{n+=parseInt(d.textContent,10)||0});return n}
function applyTray(){const hr=document.getElementById('hdrR');if(!hr)return;
 if(!MQ.matches){const t=hr.querySelector('.hrtray');if(t){[...t.children].forEach(c=>hr.insertBefore(c,t));t.remove();hr.querySelector('.hrtog')?.remove();hr.classList.remove('hastray','open')}return}
 const av=hr.querySelector('.hbtn.avatar,[data-sheet="profile"],[data-auth]')||hr.lastElementChild;if(!av)return;
 let tray=hr.querySelector(':scope>.hrtray'),tog=hr.querySelector(':scope>.hrtog');
 if(!tray){tray=document.createElement('div');tray.className='hrtray';tray.id='hrTray';hr.insertBefore(tray,hr.firstChild)}
 [...hr.children].forEach(c=>{if(c!==tray&&c!==tog&&c!==av&&!c.classList.contains('hrtog'))tray.appendChild(c)});
 if(!tog){tog=document.createElement('button');tog.className='hbtn hrtog';tog.type='button';tog.setAttribute('aria-controls','hrTray');hr.insertBefore(tog,av)}
 const n=unread(tray);tog.innerHTML=ARR+(n?`<span class="dot">${n>99?'99+':n}</span>`:'');
 tog.setAttribute('aria-expanded',String(trayOpen));tog.setAttribute('aria-label',trayOpen?'Hide menu buttons':'Show menu buttons'+(n?` (${n} new)`:''));
 hr.classList.add('hastray');hr.classList.toggle('open',trayOpen);tray.setAttribute('aria-hidden',String(!trayOpen));
 tray.querySelectorAll('button,a').forEach(b=>{if(trayOpen)b.removeAttribute('tabindex');else b.setAttribute('tabindex','-1')})}
let busy=false;const mo=new MutationObserver(()=>{if(busy)return;busy=true;try{applyTray()}finally{setTimeout(()=>busy=false,0)}});
function watch(){const hr=document.getElementById('hdrR');if(hr&&!hr.__trayWatch){hr.__trayWatch=1;mo.observe(hr,{childList:true,subtree:true,characterData:true})}applyTray()}
const _rd=render;render=function(){const r=_rd.apply(this,arguments);try{watch()}catch(_){}return r};
document.addEventListener('click',e=>{const hr=document.getElementById('hdrR');if(!hr||!hr.classList.contains('hastray'))return;
 if(e.target.closest('.hrtog')){e.preventDefault();e.stopPropagation();trayOpen=!trayOpen;applyTray();return}
 if(trayOpen&&e.target.closest('.hrtray button,.hrtray a')){setTimeout(()=>{trayOpen=false;applyTray()},120);return}
 if(trayOpen&&!e.target.closest('#hdrR')){trayOpen=false;applyTray()}},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&trayOpen){trayOpen=false;applyTray()}});
MQ.addEventListener?MQ.addEventListener('change',()=>{trayOpen=false;watch()}):0;
setTimeout(watch,0);window.__hdrTray={applyTray,get open(){return trayOpen}};
}catch(e){console.warn('hdrtray',e)}
/*HDRTRAY-END*/

