function shade(c){/* emblem accent: a deeper version of the shield colour */try{const n=parseInt(c.slice(1),16),f=x=>Math.max(0,Math.round(x*.72));return '#'+[(n>>16)&255,(n>>8)&255,n&255].map(f).map(x=>x.toString(16).padStart(2,'0')).join('')}catch(_){return INK}}
