function deepLink(){const h=decodeURIComponent(location.hash.slice(1));if(h.startsWith('open=')){const id=h.slice(5);if(BY[id]){if(S.view==='home'||!S.view)go('explore');setTimeout(()=>openItem(id),60)}return true}if(h.startsWith('post=')){S.cm.post=h.slice(5);S.cm.user=null;go('community',{keepcm:true});try{history.replaceState(null,'','#post='+S.cm.post)}catch(_){};return true}if(h.startsWith('u=')){S.cm.user=h.slice(2);S.cm.post=null;go('community',{keepcm:true});try{history.replaceState(null,'','#u='+S.cm.user)}catch(_){};return true}if(h.startsWith('q=')){go('explore',{q:h.slice(2)});return true}return false}
window.addEventListener('hashchange',()=>{if(deepLink())return;const v=location.hash.slice(1);if(v==='community'&&S.view==='community'&&((S.kn&&S.kn.open)||(S.fd&&S.fd.open))){if(S.kn)S.kn.open=null;if(S.fd)S.fd.open=null;render();return}if(NAV.some(n=>n[0]===v)&&(v!==S.view||(v==='community'&&S.cm&&(S.cm.post||S.cm.user))))go(v)});setTimeout(deepLink,300);
