;(function(){const P=window.ILLPACKS;if(!P)return;const IX=window.PACKIDX||{},done=new Set();const want=()=>{for(const el of document.querySelectorAll('img[src*="#ill="]')){const m=el.getAttribute('src').match(/#ill=([^&]+)/);const pk=m&&IX[m[1]];if(pk&&!done.has(pk))return pk}return null};const next=()=>{const rest=P.filter(x=>!done.has(x));if(!rest.length)return;const pk=(done.has('ban.js')?want():null)||rest[0];done.add(pk);const sc=document.createElement('script');sc.src='data/pack/'+pk+((window.PACKV||{})[pk]?'?v='+window.PACKV[pk]:'');sc.onload=sc.onerror=()=>setTimeout(next,30);document.head.appendChild(sc)};next();new MutationObserver(()=>window.DRAW.refreshPacks()).observe(document.body,{childList:true,subtree:true})})();
